//! Resident descriptor ABI. The certified instruction stream is generated by Lean.
//! The proof covers the abstract plan/control contract, not Metal compilation,
//! floating-point equivalence, or cross-threadgroup scheduling guarantees.
const std = @import("std");
const metal = @import("metal.zig");
pub const certified = @import("resident_plan.zig");

pub const Layer = extern struct {
    input_norm: metal.Matrix,
    post_norm: metal.Matrix,
    q: metal.Matrix,
    k: metal.Matrix,
    v: metal.Matrix,
    o: metal.Matrix,
    q_norm: metal.Matrix,
    k_norm: metal.Matrix,
    sink: metal.Matrix,
    router: metal.Matrix,
    experts: u64,
    bias: u64,
    keys: u64,
    values: u64,
    capacity: u32,
    window: u32,
    rope: u32,
    routed: u32,
    shared_index: u32,
    stride: u32,
};
pub const Descriptor = extern struct {
    embedding: metal.Matrix,
    final_norm: metal.Matrix,
    head: metal.Matrix,
    layers: u64,
    x: u64,
    norm: u64,
    q: u64,
    k: u64,
    v: u64,
    attention: u64,
    projection: u64,
    activation: u64,
    router: u64,
    route_ids: u64,
    route_weights: u64,
    logits: u64,
    hidden: u32,
    heads: u32,
    kv_heads: u32,
    dim: u32,
    layer_count: u32,
    position: u32,
    token: u32,
    workers: u32,
    eps: f32,
    theta: f32,
    row_tile: u32,
    reserved: u32 = 0,
};
pub const Control = extern struct { arrivals: u32, phase: u32, status: u32, completed: u32 };
pub const Execution = struct {
    descriptor: metal.Buffer,
    layers: metal.Buffer,
    program: metal.Buffer,
    control: metal.Buffer,
    workers: u32,
};

pub fn vector(w: @import("weights.zig").Weight) metal.Matrix {
    return .{ .weight = w.buffer.address() + w.tensor.offset, .rows = 1, .cols = @intCast(w.tensor.shape[0]), .dtype = @backingInt(w.tensor.dtype) };
}

test "resident ABI and certified instruction bounds" {
    try std.testing.expectEqual(@as(usize, 616), @sizeOf(Layer));
    try std.testing.expectEqual(@as(usize, 320), @sizeOf(Descriptor));
    try std.testing.expectEqual(@as(usize, 16), @sizeOf(Control));
    try std.testing.expect(certified.program(0) == null);
    try std.testing.expect(certified.program(certified.max_layers + 1) == null);
    const program = certified.program(49).?;
    try std.testing.expectEqual(@as(usize, 493), program.len);
    try std.testing.expectEqual(@as(u32, 1), program[0]);
    try std.testing.expectEqual(@as(u32, 12), program[program.len - 2]);
    try std.testing.expectEqual(@as(u32, 13), program[program.len - 1]);
}

test "resident phase barrier progresses and rejects poisoned control" {
    const ctx = try metal.Context.init();
    defer ctx.deinit();
    const control = try ctx.alloc(4);
    defer control.deinit();
    const diagnostic = try ctx.alloc(4);
    defer diagnostic.deinit();
    for ([_]u32{ 1, 4 }) |workers| {
        @memset(control.structs(u32), 0);
        @memset(diagnostic.structs(u32), 99);
        try ctx.dispatch("resident_barrier_probe", &.{ control, diagnostic }, .{ .n = 20, .m = workers }, workers * certified.threadgroup_size, certified.threadgroup_size);
        try ctx.finish();
        try std.testing.expectEqual(@as(u32, 0), control.structs(u32)[2]);
        try std.testing.expectEqual(@as(u32, 20), control.structs(u32)[1]);
        for (diagnostic.structs(u32)[0..workers]) |value| try std.testing.expectEqual(@as(u32, 0), value);
    }
    @memset(control.structs(u32), 0);
    control.structs(u32)[2] = 2;
    @memset(diagnostic.structs(u32), 0);
    try ctx.dispatch("resident_barrier_probe", &.{ control, diagnostic }, .{ .n = 20, .m = 4 }, 4 * certified.threadgroup_size, certified.threadgroup_size);
    try ctx.finish();
    try std.testing.expectEqual(@as(u32, 2), control.structs(u32)[2]);
    for (diagnostic.structs(u32)) |value| try std.testing.expect(value > 0);
}
